import{_ as l,l as r,o as e,c as o,v as t,p as d,x as s,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"CPI 与阿姆达尔","description":"","frontmatter":{"title":"CPI 与阿姆达尔","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cpi-amdahl.md","filePath":"cs/cpi-amdahl.md","lastUpdated":1789023840000}'),h={name:"cs/cpi-amdahl.md"};function m(P,a,C,_,A,E){const i=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="cpi-与阿姆达尔" tabindex="-1">CPI 与阿姆达尔 <a class="header-anchor" href="#cpi-与阿姆达尔" aria-label="Permalink to &quot;CPI 与阿姆达尔&quot;">​</a></h1><div class="epigraph"><p>加速比被未改进部分卡住；把流水线的理想 CPI 写成 1，真正的时间仍在停顿和那一小段加速不了的工作里。</p><footer>—— 据 Amdahl, Validity of the single processor approach to achieving large scale computing capabilities, AFIPS 1967 整理</footer></div><p><a href="/cs/delay-slot">上一课</a>把精确异常钉在提交点上，冲刷会丢掉已经取进来的指令。五级、转发、预测、异常路径至此都有了对象。本课不重讲任何一种冒险怎么修。缺口是：还没有把「每条指令多少拍」和「改进一块能快多少」写成可加减的量。本课只交出 CPI 分解和阿姆达尔定律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理想五级的 CPI 是 1。结构气泡、load-use、误预测冲刷、陷阱入口都把平均 CPI 抬高。只说「流水线更快」无法比较两种设计：时钟可能更高，但停顿也可能更多。缺口不是再发明一级流水线，而是<strong>CPU 时间 = 指令数 × CPI × 时钟周期</strong>，并把 CPI 拆成基础 1 加上各类停顿。</p><p>Amdahl 进一步问：若只有比例 \\(f\\) 的时间被加速 \\(s\\) 倍，整体加速比是 \\(1/((1-f)+f/s)\\)。把全部面积砸在已经很短的那一段上，收益趋零。本课不把定律用到多核负载均衡以外的故事；多核是后课。</p><p><span class="marginnote">Amdahl 1967 的原文针对「单处理器思路能否靠加速一部分达到大规模」；教学上用来约束任何局部优化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(\\mathrm{CPI} = \\mathrm{CPI}_\\text{ideal} + \\sum_i \\text{停顿}_i\\)。五级理想项取 1；停顿按结构、数据、控制、异常分别计数，再按指令频率加权。CPU 时间用这条乘时钟。比较设计时，同时看时钟能否缩短——转发 mux 可能让周期变长，净效果不一定赢。</p>',9)),(e(),d(c,null,{default:s(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INST%5B%22%E6%8C%87%E4%BB%A4%E6%95%B0%22%5D%20--%3E%20T%5B%22CPU%20%E6%97%B6%E9%97%B4%22%5D%0A%20%20CPI%5B%22CPI%20%3D%201%20%2B%20%E5%81%9C%E9%A1%BF%22%5D%20--%3E%20T%0A%20%20CLK%5B%22%E6%97%B6%E9%92%9F%E5%91%A8%E6%9C%9F%22%5D%20--%3E%20T%0A%20%20T%20--%3E%20A%5B%22%E9%98%BF%E5%A7%86%E8%BE%BE%E5%B0%94%EF%BC%9A%E6%9C%AA%E5%8A%A0%E9%80%9F%E9%83%A8%E5%88%86%E5%B0%81%E9%A1%B6%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>加速比 \\(S = T_\\text{old}/T_\\text{new}\\)。若只改进分支预测，把 \\(f\\) 取成原先花在误预测冲刷上的时间比例，\\(s\\) 取成该项的局部加速，整体 \\(S\\) 立刻小于 \\(s\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定量以后，后课 cache 缺失、TLB 失效都可以加进同一条 CPI 公式，而不必改 ISA。局部性课要解释为什么存储器停顿会主导这项；本课只把公式的位置留好。</p><p>阿姆达尔也解释为什么要把常见路径做快：指令频率高的那类停顿，值得加硬件；罕见陷阱路径可以慢。这与特权级里「陷阱罕见」一致，不引入新的保护模型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IPC 大于 1：那是<a href="/cs/superscalar-issue">超标量发射</a>把理想项改成小于 1 的写法。也不把定律误写成「永远只能加速 20%」——\\(f\\) 来自测量，不是常数。Gustafson 的按比例放大是另一种问题，主干不在这里展开。</p><p>后课默认：谈到性能，先写指令数、CPI、周期三项；cache 与 VM 的缺失延迟加在 CPI 的停顿项里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPU 时间 = 指令数 × CPI × 周期；五级理想 CPI 为 1，停顿另加。</li><li>阿姆达尔：整体加速被未改进比例封顶。</li><li>存储器层次与超标量会改写 CPI 的项，对象仍是这条公式。</li><li>出处：Amdahl, AFIPS 1967；Hennessy and Patterson, <em>CA:AQA</em> 第 1 章。</li></ul>',9))])}const f=l(h,[["render",m]]);export{I as __pageData,f as default};
